window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9465677856e8c6ae"]={"versions": [{"id": "FIG-9465677856e8c6ae", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionsblockdiagramm / Signalfluss- und Arbitrierungsarchitektur (Datenflussmodell für Sollwertkoordination).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R4.0.3), Konzeptdomäne <em>Application Interfaces for Powertrain</em> (<code>AUTOSAR_EXP_AIPowertrain</code>).</li>\n<li><strong>Technischer Zweck:</strong> Zweistufige Arbitrierungs- und Verteilungslogik des Powertrain Coordinators (PTC) zur Zusammenführung von Vortriebsanforderungen aus Fahrerwunsch, Fahrgeschwindigkeits-/Längsregelung (Vehicle Longitudinal Control, VLC) und Fahrdynamikregelung (Electronic Stability Control, ESC mit ASR/MSR) unter Aufteilung in einen schnellen (Fast Path) und langsamen (Slow Path) Stellpfad.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Funktionsblöcke (SW-C-intern / Subsystemebene)</p>\n<ul class=\"fig-list\">\n<li><strong>Powertrain Coordinator (PTC):</strong> Zentrale SW-C zur Drehmomentenkoordination im Antriebsstrang.</li>\n<li><strong>1st Level Arbitration:</strong> Arbitrierungsstufe zwischen Fahrerwunsch und Fahrerassistenz (VLC).</li>\n<li><code>Max</code>-Glied: Auswahl des Maximums aus Fahrerwunsch und VLC-Mindestgrenze.</li>\n<li><code>Min</code>-Glied: Begrenzung durch die VLC-Höchstgrenze.</li>\n<li>Komparator (<code>=</code>): Detektion der Fahrerübersteuerung (<em>Driver Override</em>).</li>\n<li><strong>Conversion to wheel TQ (3 Instanzen):</strong> Physikalische Koordinatentransformation von Kupplungsmoment (<code>Clu</code>) auf Radmoment (<code>Whl</code>) unter Berücksichtigung von Triebstrangübersetzung und Wirkungsgrad.</li>\n<li><strong>2nd Level Arbitration:</strong> Arbitrierungsstufe zur Einbindung sicherheitskritischer Chassis-Eingriffe (ESC).</li>\n<li><code>Slow Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für träge Drehmomentstellglieder.</li>\n<li><code>Fast Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für hochdynamische Drehmomentstellglieder.</li>\n<li><strong>Actuator Coordination / Distribution (<code>...</code>):</strong> Nachgelagerte Momentenaufteilung auf physikalische Aktuatoren (z. B. Zündung/Einspritzung vs. Luftpfad bzw. E-Maschine/Inverter).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Ports (Sender-Receiver-Signale)</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsdaten (Input Ports / Data Elements):</strong></li>\n<li><code>DrvReqTqWhlFast</code>: Fahrer-Wunschmoment am Rad über schnellen Pfad (Pedalinterpretation).</li>\n<li><code>VlcTqWhlPtMin</code>: Minimales gefordertes Radmoment der Längsführung (z. B. Beschleunigungsanforderung ACC).</li>\n<li><code>VlcTqWhlPtMax</code>: Maximales zulässiges Radmoment der Längsführung (z. B. Verzögerungsanforderung ACC/Limiter).</li>\n<li><code>EscTqCluPtMaxSlow</code>: ASR-Begrenzungsmoment an der Kupplung für den langsamen Pfad (Füllungsregelung / Drosselklappe).</li>\n<li><code>EscTqCluPtMin</code>: MSR-Mindestmoment an der Kupplung (Schleppmoment-Regelung zur Vermeidung von Radblockaden).</li>\n<li><code>EscTqCluPtMaxFast</code>: ASR-Begrenzungsmoment an der Kupplung für den schnellen Pfad (Zündwinkelverstellung / Einspritzabblendung / E-Maschine).</li>\n<li><strong>Ausgangsdaten & Zustandsflags (Output Ports / Data Elements):</strong></li>\n<li><code>PtTqWhlReqDrvVlc</code>: Resultierendes Führungsmoment am Rad nach Stufe 1.</li>\n<li><code>PtFlgDrvOvrdVlc</code>: Diskretes Steuerflag (<code>1</code>, wenn <code>DrvReqTqWhlFast == PtTqWhlReqDrvVlc</code>), signalisiert aktives Übersteuern des VLC durch den Fahrer.</li>\n<li><code>Slow setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit hoher Reaktionszeitkonstante.</li>\n<li><code>Fast Setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit minimaler Reaktionszeitkonstante.</li>\n<li><code>PtTqWhl</code>: Vom Gesamtsystem am Rad bereitgestelltes Gesamtmoment (<em>Total wheel torque</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung erfolgt deterministisch im zyklischen Runnable-Kontext (periodische RTE-Events).</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1 (Führungsarbitrierung - Komfortebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung des vorläufigen Fahrer/VLC-Momentenwunsches:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Interm} = \\max(\\text{DrvReqTqWhlFast}, \\text{VlcTqWhlPtMin})$$</p>\n<p class=\"fig-p\">$$\\text{PtTqWhlReqDrvVlc} = \\min(\\text{Interm}, \\text{VlcTqWhlPtMax})$$</p>\n<ul class=\"fig-list\">\n<li>Evaluierung des Override-Flags:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{PtFlgDrvOvrdVlc} = (\\text{DrvReqTqWhlFast} \\equiv \\text{PtTqWhlReqDrvVlc})$$</p>\n<ol class=\"fig-list\">\n<li><strong>Koordinatentransformation (Clutch $\\to$ Wheel):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone Umrechnung der ESC-Kupplungsmomente in Radmomente über die aktuelle Gesamtübersetzung $i_{\\text{gear}} \\cdot i_{\\text{diff}}$:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{Whl}} = T_{\\text{Clu}} \\cdot i_{\\text{tot}} \\cdot \\eta_{\\text{driveline}}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2 (Sicherheitsarbitrierung - Chassisebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>MSR-Dominanz (<code>Max</code>-Glieder):</strong> Sowohl im Slow- als auch im Fast-Pfad wird das Vortriebsmoment nach unten durch das umgerechnete <code>EscTqCluPtMin</code> begrenzt, um Schlupf bei starkem Motorbremsmoment abzufangen:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{path, base}} = \\max(\\text{PtTqWhlReqDrvVlc}, \\text{EscTqCluPtMin\\_whl})$$</p>\n<ul class=\"fig-list\">\n<li><strong>ASR-Dominanz (<code>Min</code>-Glieder):</strong></li>\n<li><strong>Slow Path:</strong> Begrenzung auf <code>EscTqCluPtMaxSlow_whl</code> liefert <code>Slow setpoint</code>.</li>\n<li><strong>Fast Path:</strong> Begrenzung auf <code>EscTqCluPtMaxFast_whl</code> liefert <code>Fast Setpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuatorische Distribution:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weitergabe an das nachgelagerte Motormanagement zur koordinierten Ansteuerung von Momentenstellgliedern unterschiedlicher Dynamik.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus (EXP):</strong> Das Dokument ist informativ/erläuternd (<em>Explanatory</em>). Die Struktur definiert empfohlene Application Interfaces (Port-Definitionen und Typisierung), schreibt jedoch nicht die interne Implementierungstopologie zwingend vor.</li>\n<li><strong>Inkonsistenz der Referenzebenen (Wheel vs. Clutch):</strong></li>\n<li>Eingangssignale mischen Radmomente (VLC, Fahrer) und Kupplungsmomente (ESC).</li>\n<li><em>Implementierungsfalle:</em> Die Blöcke <code>Conversion to wheel TQ</code> müssen bei Schaltvorgängen, Wandlerüberhöhung oder getrennter Kupplung hochdynamisch abgesichert werden. Bei offener Kupplung ($i_{\\text{tot}} \\to 0$ bzw. undefiniert) droht Division durch Null oder fehlerhafte Momentenskalierung.</li>\n<li><strong>Numerik des Komparators (<code>=</code>):</strong></li>\n<li>Der Komparator für <code>PtFlgDrvOvrdVlc</code> vergleicht Gleitkommagrößen (<code>float32</code> nach AUTOSAR-Standard). Ein direkter Identitätsvergleich (<code>==</code>) ist in Fixed-Point- oder Floating-Point-Arithmetik unzulässig; im Runnable muss ein Toleranzband ($|\\Delta T| \\le \\varepsilon$) mit Entprellung/Hysterese implementiert werden.</li>\n<li><strong>Echtzeit- und Task-Mapping:</strong></li>\n<li>Der <code>Fast Path</code> erfordert typischerweise ein Mapping in eine hochpriore, zyklische Task (z. B. $1\\,\\text{ms}$ bis $5\\,\\text{ms}$), um Stabilitätseingriffe des ESC verzögerungsarm abzubilden.</li>\n<li>Der <code>Slow Path</code> wird in der Regel in einer $10\\,\\text{ms}$- bis $20\\,\\text{ms}$-Task berechnet.</li>\n<li>Phasenverschiebungen und Totzeiten zwischen beiden Pfaden müssen im PTC über Momentenrampen und Vorsteuerfilter abgefangen werden, um Ruckeln und Triebstrangschwingungen zu verhindern.</li>\n</ul>"}, {"id": "FIG-1158af8e5d747ad7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionsblockdiagramm / Signalfluss- und Arbitrierungsarchitektur (Datenflussmodell für Sollwertkoordination).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R4.0.3), Konzeptdomäne <em>Application Interfaces for Powertrain</em> (<code>AUTOSAR_EXP_AIPowertrain</code>).</li>\n<li><strong>Technischer Zweck:</strong> Zweistufige Arbitrierungs- und Verteilungslogik des Powertrain Coordinators (PTC) zur Zusammenführung von Vortriebsanforderungen aus Fahrerwunsch, Fahrgeschwindigkeits-/Längsregelung (Vehicle Longitudinal Control, VLC) und Fahrdynamikregelung (Electronic Stability Control, ESC mit ASR/MSR) unter Aufteilung in einen schnellen (Fast Path) und langsamen (Slow Path) Stellpfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Funktionsblöcke (SW-C-intern / Subsystemebene)</p>\n<ul class=\"fig-list\">\n<li><strong>Powertrain Coordinator (PTC):</strong> Zentrale SW-C zur Drehmomentenkoordination im Antriebsstrang.</li>\n<li><strong>1st Level Arbitration:</strong> Arbitrierungsstufe zwischen Fahrerwunsch und Fahrerassistenz (VLC).</li>\n<li><code>Max</code>-Glied: Auswahl des Maximums aus Fahrerwunsch und VLC-Mindestgrenze.</li>\n<li><code>Min</code>-Glied: Begrenzung durch die VLC-Höchstgrenze.</li>\n<li>Komparator (<code>=</code>): Detektion der Fahrerübersteuerung (<em>Driver Override</em>).</li>\n<li><strong>Conversion to wheel TQ (3 Instanzen):</strong> Physikalische Koordinatentransformation von Kupplungsmoment (<code>Clu</code>) auf Radmoment (<code>Whl</code>) unter Berücksichtigung von Triebstrangübersetzung und Wirkungsgrad.</li>\n<li><strong>2nd Level Arbitration:</strong> Arbitrierungsstufe zur Einbindung sicherheitskritischer Chassis-Eingriffe (ESC).</li>\n<li><code>Slow Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für träge Drehmomentstellglieder.</li>\n<li><code>Fast Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für hochdynamische Drehmomentstellglieder.</li>\n<li><strong>Actuator Coordination / Distribution (<code>...</code>):</strong> Nachgelagerte Momentenaufteilung auf physikalische Aktuatoren (z. B. Zündung/Einspritzung vs. Luftpfad bzw. E-Maschine/Inverter).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Ports (Sender-Receiver-Signale)</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsdaten (Input Ports / Data Elements):</strong></li>\n<li><code>DrvReqTqWhlFast</code>: Fahrer-Wunschmoment am Rad über schnellen Pfad (Pedalinterpretation).</li>\n<li><code>VlcTqWhlPtMin</code>: Minimales gefordertes Radmoment der Längsführung (z. B. Beschleunigungsanforderung ACC).</li>\n<li><code>VlcTqWhlPtMax</code>: Maximales zulässiges Radmoment der Längsführung (z. B. Verzögerungsanforderung ACC/Limiter).</li>\n<li><code>EscTqCluPtMaxSlow</code>: ASR-Begrenzungsmoment an der Kupplung für den langsamen Pfad (Füllungsregelung / Drosselklappe).</li>\n<li><code>EscTqCluPtMin</code>: MSR-Mindestmoment an der Kupplung (Schleppmoment-Regelung zur Vermeidung von Radblockaden).</li>\n<li><code>EscTqCluPtMaxFast</code>: ASR-Begrenzungsmoment an der Kupplung für den schnellen Pfad (Zündwinkelverstellung / Einspritzabblendung / E-Maschine).</li>\n<li><strong>Ausgangsdaten & Zustandsflags (Output Ports / Data Elements):</strong></li>\n<li><code>PtTqWhlReqDrvVlc</code>: Resultierendes Führungsmoment am Rad nach Stufe 1.</li>\n<li><code>PtFlgDrvOvrdVlc</code>: Diskretes Steuerflag (<code>1</code>, wenn <code>DrvReqTqWhlFast == PtTqWhlReqDrvVlc</code>), signalisiert aktives Übersteuern des VLC durch den Fahrer.</li>\n<li><code>Slow setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit hoher Reaktionszeitkonstante.</li>\n<li><code>Fast Setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit minimaler Reaktionszeitkonstante.</li>\n<li><code>PtTqWhl</code>: Vom Gesamtsystem am Rad bereitgestelltes Gesamtmoment (<em>Total wheel torque</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung erfolgt deterministisch im zyklischen Runnable-Kontext (periodische RTE-Events).</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1 (Führungsarbitrierung - Komfortebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung des vorläufigen Fahrer/VLC-Momentenwunsches:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Interm} = \\max(\\text{DrvReqTqWhlFast}, \\text{VlcTqWhlPtMin})$$</p>\n<p class=\"fig-p\">$$\\text{PtTqWhlReqDrvVlc} = \\min(\\text{Interm}, \\text{VlcTqWhlPtMax})$$</p>\n<ul class=\"fig-list\">\n<li>Evaluierung des Override-Flags:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{PtFlgDrvOvrdVlc} = (\\text{DrvReqTqWhlFast} \\equiv \\text{PtTqWhlReqDrvVlc})$$</p>\n<ol class=\"fig-list\">\n<li><strong>Koordinatentransformation (Clutch $\\to$ Wheel):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone Umrechnung der ESC-Kupplungsmomente in Radmomente über die aktuelle Gesamtübersetzung $i_{\\text{gear}} \\cdot i_{\\text{diff}}$:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{Whl}} = T_{\\text{Clu}} \\cdot i_{\\text{tot}} \\cdot \\eta_{\\text{driveline}}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2 (Sicherheitsarbitrierung - Chassisebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>MSR-Dominanz (<code>Max</code>-Glieder):</strong> Sowohl im Slow- als auch im Fast-Pfad wird das Vortriebsmoment nach unten durch das umgerechnete <code>EscTqCluPtMin</code> begrenzt, um Schlupf bei starkem Motorbremsmoment abzufangen:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{path, base}} = \\max(\\text{PtTqWhlReqDrvVlc}, \\text{EscTqCluPtMin\\_whl})$$</p>\n<ul class=\"fig-list\">\n<li><strong>ASR-Dominanz (<code>Min</code>-Glieder):</strong></li>\n<li><strong>Slow Path:</strong> Begrenzung auf <code>EscTqCluPtMaxSlow_whl</code> liefert <code>Slow setpoint</code>.</li>\n<li><strong>Fast Path:</strong> Begrenzung auf <code>EscTqCluPtMaxFast_whl</code> liefert <code>Fast Setpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuatorische Distribution:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weitergabe an das nachgelagerte Motormanagement zur koordinierten Ansteuerung von Momentenstellgliedern unterschiedlicher Dynamik.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus (EXP):</strong> Das Dokument ist informativ/erläuternd (<em>Explanatory</em>). Die Struktur definiert empfohlene Application Interfaces (Port-Definitionen und Typisierung), schreibt jedoch nicht die interne Implementierungstopologie zwingend vor.</li>\n<li><strong>Inkonsistenz der Referenzebenen (Wheel vs. Clutch):</strong></li>\n<li>Eingangssignale mischen Radmomente (VLC, Fahrer) und Kupplungsmomente (ESC).</li>\n<li><em>Implementierungsfalle:</em> Die Blöcke <code>Conversion to wheel TQ</code> müssen bei Schaltvorgängen, Wandlerüberhöhung oder getrennter Kupplung hochdynamisch abgesichert werden. Bei offener Kupplung ($i_{\\text{tot}} \\to 0$ bzw. undefiniert) droht Division durch Null oder fehlerhafte Momentenskalierung.</li>\n<li><strong>Numerik des Komparators (<code>=</code>):</strong></li>\n<li>Der Komparator für <code>PtFlgDrvOvrdVlc</code> vergleicht Gleitkommagrößen (<code>float32</code> nach AUTOSAR-Standard). Ein direkter Identitätsvergleich (<code>==</code>) ist in Fixed-Point- oder Floating-Point-Arithmetik unzulässig; im Runnable muss ein Toleranzband ($|\\Delta T| \\le \\varepsilon$) mit Entprellung/Hysterese implementiert werden.</li>\n<li><strong>Echtzeit- und Task-Mapping:</strong></li>\n<li>Der <code>Fast Path</code> erfordert typischerweise ein Mapping in eine hochpriore, zyklische Task (z. B. $1\\,\\text{ms}$ bis $5\\,\\text{ms}$), um Stabilitätseingriffe des ESC verzögerungsarm abzubilden.</li>\n<li>Der <code>Slow Path</code> wird in der Regel in einer $10\\,\\text{ms}$- bis $20\\,\\text{ms}$-Task berechnet.</li>\n<li>Phasenverschiebungen und Totzeiten zwischen beiden Pfaden müssen im PTC über Momentenrampen und Vorsteuerfilter abgefangen werden, um Ruckeln und Triebstrangschwingungen zu verhindern.</li>\n</ul>"}, {"id": "FIG-eeed95f6cec5f481", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionsblockdiagramm / Signalfluss- und Arbitrierungsarchitektur (Datenflussmodell für Sollwertkoordination).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R4.0.3), Konzeptdomäne <em>Application Interfaces for Powertrain</em> (<code>AUTOSAR_EXP_AIPowertrain</code>).</li>\n<li><strong>Technischer Zweck:</strong> Zweistufige Arbitrierungs- und Verteilungslogik des Powertrain Coordinators (PTC) zur Zusammenführung von Vortriebsanforderungen aus Fahrerwunsch, Fahrgeschwindigkeits-/Längsregelung (Vehicle Longitudinal Control, VLC) und Fahrdynamikregelung (Electronic Stability Control, ESC mit ASR/MSR) unter Aufteilung in einen schnellen (Fast Path) und langsamen (Slow Path) Stellpfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Funktionsblöcke (SW-C-intern / Subsystemebene)</p>\n<ul class=\"fig-list\">\n<li><strong>Powertrain Coordinator (PTC):</strong> Zentrale SW-C zur Drehmomentenkoordination im Antriebsstrang.</li>\n<li><strong>1st Level Arbitration:</strong> Arbitrierungsstufe zwischen Fahrerwunsch und Fahrerassistenz (VLC).</li>\n<li><code>Max</code>-Glied: Auswahl des Maximums aus Fahrerwunsch und VLC-Mindestgrenze.</li>\n<li><code>Min</code>-Glied: Begrenzung durch die VLC-Höchstgrenze.</li>\n<li>Komparator (<code>=</code>): Detektion der Fahrerübersteuerung (<em>Driver Override</em>).</li>\n<li><strong>Conversion to wheel TQ (3 Instanzen):</strong> Physikalische Koordinatentransformation von Kupplungsmoment (<code>Clu</code>) auf Radmoment (<code>Whl</code>) unter Berücksichtigung von Triebstrangübersetzung und Wirkungsgrad.</li>\n<li><strong>2nd Level Arbitration:</strong> Arbitrierungsstufe zur Einbindung sicherheitskritischer Chassis-Eingriffe (ESC).</li>\n<li><code>Slow Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für träge Drehmomentstellglieder.</li>\n<li><code>Fast Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für hochdynamische Drehmomentstellglieder.</li>\n<li><strong>Actuator Coordination / Distribution (<code>...</code>):</strong> Nachgelagerte Momentenaufteilung auf physikalische Aktuatoren (z. B. Zündung/Einspritzung vs. Luftpfad bzw. E-Maschine/Inverter).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Ports (Sender-Receiver-Signale)</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsdaten (Input Ports / Data Elements):</strong></li>\n<li><code>DrvReqTqWhlFast</code>: Fahrer-Wunschmoment am Rad über schnellen Pfad (Pedalinterpretation).</li>\n<li><code>VlcTqWhlPtMin</code>: Minimales gefordertes Radmoment der Längsführung (z. B. Beschleunigungsanforderung ACC).</li>\n<li><code>VlcTqWhlPtMax</code>: Maximales zulässiges Radmoment der Längsführung (z. B. Verzögerungsanforderung ACC/Limiter).</li>\n<li><code>EscTqCluPtMaxSlow</code>: ASR-Begrenzungsmoment an der Kupplung für den langsamen Pfad (Füllungsregelung / Drosselklappe).</li>\n<li><code>EscTqCluPtMin</code>: MSR-Mindestmoment an der Kupplung (Schleppmoment-Regelung zur Vermeidung von Radblockaden).</li>\n<li><code>EscTqCluPtMaxFast</code>: ASR-Begrenzungsmoment an der Kupplung für den schnellen Pfad (Zündwinkelverstellung / Einspritzabblendung / E-Maschine).</li>\n<li><strong>Ausgangsdaten & Zustandsflags (Output Ports / Data Elements):</strong></li>\n<li><code>PtTqWhlReqDrvVlc</code>: Resultierendes Führungsmoment am Rad nach Stufe 1.</li>\n<li><code>PtFlgDrvOvrdVlc</code>: Diskretes Steuerflag (<code>1</code>, wenn <code>DrvReqTqWhlFast == PtTqWhlReqDrvVlc</code>), signalisiert aktives Übersteuern des VLC durch den Fahrer.</li>\n<li><code>Slow setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit hoher Reaktionszeitkonstante.</li>\n<li><code>Fast Setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit minimaler Reaktionszeitkonstante.</li>\n<li><code>PtTqWhl</code>: Vom Gesamtsystem am Rad bereitgestelltes Gesamtmoment (<em>Total wheel torque</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung erfolgt deterministisch im zyklischen Runnable-Kontext (periodische RTE-Events).</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1 (Führungsarbitrierung - Komfortebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung des vorläufigen Fahrer/VLC-Momentenwunsches:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Interm} = \\max(\\text{DrvReqTqWhlFast}, \\text{VlcTqWhlPtMin})$$</p>\n<p class=\"fig-p\">$$\\text{PtTqWhlReqDrvVlc} = \\min(\\text{Interm}, \\text{VlcTqWhlPtMax})$$</p>\n<ul class=\"fig-list\">\n<li>Evaluierung des Override-Flags:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{PtFlgDrvOvrdVlc} = (\\text{DrvReqTqWhlFast} \\equiv \\text{PtTqWhlReqDrvVlc})$$</p>\n<ol class=\"fig-list\">\n<li><strong>Koordinatentransformation (Clutch $\\to$ Wheel):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone Umrechnung der ESC-Kupplungsmomente in Radmomente über die aktuelle Gesamtübersetzung $i_{\\text{gear}} \\cdot i_{\\text{diff}}$:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{Whl}} = T_{\\text{Clu}} \\cdot i_{\\text{tot}} \\cdot \\eta_{\\text{driveline}}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2 (Sicherheitsarbitrierung - Chassisebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>MSR-Dominanz (<code>Max</code>-Glieder):</strong> Sowohl im Slow- als auch im Fast-Pfad wird das Vortriebsmoment nach unten durch das umgerechnete <code>EscTqCluPtMin</code> begrenzt, um Schlupf bei starkem Motorbremsmoment abzufangen:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{path, base}} = \\max(\\text{PtTqWhlReqDrvVlc}, \\text{EscTqCluPtMin\\_whl})$$</p>\n<ul class=\"fig-list\">\n<li><strong>ASR-Dominanz (<code>Min</code>-Glieder):</strong></li>\n<li><strong>Slow Path:</strong> Begrenzung auf <code>EscTqCluPtMaxSlow_whl</code> liefert <code>Slow setpoint</code>.</li>\n<li><strong>Fast Path:</strong> Begrenzung auf <code>EscTqCluPtMaxFast_whl</code> liefert <code>Fast Setpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuatorische Distribution:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weitergabe an das nachgelagerte Motormanagement zur koordinierten Ansteuerung von Momentenstellgliedern unterschiedlicher Dynamik.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus (EXP):</strong> Das Dokument ist informativ/erläuternd (<em>Explanatory</em>). Die Struktur definiert empfohlene Application Interfaces (Port-Definitionen und Typisierung), schreibt jedoch nicht die interne Implementierungstopologie zwingend vor.</li>\n<li><strong>Inkonsistenz der Referenzebenen (Wheel vs. Clutch):</strong></li>\n<li>Eingangssignale mischen Radmomente (VLC, Fahrer) und Kupplungsmomente (ESC).</li>\n<li><em>Implementierungsfalle:</em> Die Blöcke <code>Conversion to wheel TQ</code> müssen bei Schaltvorgängen, Wandlerüberhöhung oder getrennter Kupplung hochdynamisch abgesichert werden. Bei offener Kupplung ($i_{\\text{tot}} \\to 0$ bzw. undefiniert) droht Division durch Null oder fehlerhafte Momentenskalierung.</li>\n<li><strong>Numerik des Komparators (<code>=</code>):</strong></li>\n<li>Der Komparator für <code>PtFlgDrvOvrdVlc</code> vergleicht Gleitkommagrößen (<code>float32</code> nach AUTOSAR-Standard). Ein direkter Identitätsvergleich (<code>==</code>) ist in Fixed-Point- oder Floating-Point-Arithmetik unzulässig; im Runnable muss ein Toleranzband ($|\\Delta T| \\le \\varepsilon$) mit Entprellung/Hysterese implementiert werden.</li>\n<li><strong>Echtzeit- und Task-Mapping:</strong></li>\n<li>Der <code>Fast Path</code> erfordert typischerweise ein Mapping in eine hochpriore, zyklische Task (z. B. $1\\,\\text{ms}$ bis $5\\,\\text{ms}$), um Stabilitätseingriffe des ESC verzögerungsarm abzubilden.</li>\n<li>Der <code>Slow Path</code> wird in der Regel in einer $10\\,\\text{ms}$- bis $20\\,\\text{ms}$-Task berechnet.</li>\n<li>Phasenverschiebungen und Totzeiten zwischen beiden Pfaden müssen im PTC über Momentenrampen und Vorsteuerfilter abgefangen werden, um Ruckeln und Triebstrangschwingungen zu verhindern.</li>\n</ul>"}, {"id": "FIG-43daa69d30a3d4b6", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionsblockdiagramm / Signalfluss- und Arbitrierungsarchitektur (Datenflussmodell für Sollwertkoordination).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R4.0.3), Konzeptdomäne <em>Application Interfaces for Powertrain</em> (<code>AUTOSAR_EXP_AIPowertrain</code>).</li>\n<li><strong>Technischer Zweck:</strong> Zweistufige Arbitrierungs- und Verteilungslogik des Powertrain Coordinators (PTC) zur Zusammenführung von Vortriebsanforderungen aus Fahrerwunsch, Fahrgeschwindigkeits-/Längsregelung (Vehicle Longitudinal Control, VLC) und Fahrdynamikregelung (Electronic Stability Control, ESC mit ASR/MSR) unter Aufteilung in einen schnellen (Fast Path) und langsamen (Slow Path) Stellpfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Funktionsblöcke (SW-C-intern / Subsystemebene)</p>\n<ul class=\"fig-list\">\n<li><strong>Powertrain Coordinator (PTC):</strong> Zentrale SW-C zur Drehmomentenkoordination im Antriebsstrang.</li>\n<li><strong>1st Level Arbitration:</strong> Arbitrierungsstufe zwischen Fahrerwunsch und Fahrerassistenz (VLC).</li>\n<li><code>Max</code>-Glied: Auswahl des Maximums aus Fahrerwunsch und VLC-Mindestgrenze.</li>\n<li><code>Min</code>-Glied: Begrenzung durch die VLC-Höchstgrenze.</li>\n<li>Komparator (<code>=</code>): Detektion der Fahrerübersteuerung (<em>Driver Override</em>).</li>\n<li><strong>Conversion to wheel TQ (3 Instanzen):</strong> Physikalische Koordinatentransformation von Kupplungsmoment (<code>Clu</code>) auf Radmoment (<code>Whl</code>) unter Berücksichtigung von Triebstrangübersetzung und Wirkungsgrad.</li>\n<li><strong>2nd Level Arbitration:</strong> Arbitrierungsstufe zur Einbindung sicherheitskritischer Chassis-Eingriffe (ESC).</li>\n<li><code>Slow Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für träge Drehmomentstellglieder.</li>\n<li><code>Fast Path</code>: Serielles <code>Max</code>- gefolgt von <code>Min</code>-Glied für hochdynamische Drehmomentstellglieder.</li>\n<li><strong>Actuator Coordination / Distribution (<code>...</code>):</strong> Nachgelagerte Momentenaufteilung auf physikalische Aktuatoren (z. B. Zündung/Einspritzung vs. Luftpfad bzw. E-Maschine/Inverter).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Ports (Sender-Receiver-Signale)</p>\n<ul class=\"fig-list\">\n<li><strong>Eingangsdaten (Input Ports / Data Elements):</strong></li>\n<li><code>DrvReqTqWhlFast</code>: Fahrer-Wunschmoment am Rad über schnellen Pfad (Pedalinterpretation).</li>\n<li><code>VlcTqWhlPtMin</code>: Minimales gefordertes Radmoment der Längsführung (z. B. Beschleunigungsanforderung ACC).</li>\n<li><code>VlcTqWhlPtMax</code>: Maximales zulässiges Radmoment der Längsführung (z. B. Verzögerungsanforderung ACC/Limiter).</li>\n<li><code>EscTqCluPtMaxSlow</code>: ASR-Begrenzungsmoment an der Kupplung für den langsamen Pfad (Füllungsregelung / Drosselklappe).</li>\n<li><code>EscTqCluPtMin</code>: MSR-Mindestmoment an der Kupplung (Schleppmoment-Regelung zur Vermeidung von Radblockaden).</li>\n<li><code>EscTqCluPtMaxFast</code>: ASR-Begrenzungsmoment an der Kupplung für den schnellen Pfad (Zündwinkelverstellung / Einspritzabblendung / E-Maschine).</li>\n<li><strong>Ausgangsdaten & Zustandsflags (Output Ports / Data Elements):</strong></li>\n<li><code>PtTqWhlReqDrvVlc</code>: Resultierendes Führungsmoment am Rad nach Stufe 1.</li>\n<li><code>PtFlgDrvOvrdVlc</code>: Diskretes Steuerflag (<code>1</code>, wenn <code>DrvReqTqWhlFast == PtTqWhlReqDrvVlc</code>), signalisiert aktives Übersteuern des VLC durch den Fahrer.</li>\n<li><code>Slow setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit hoher Reaktionszeitkonstante.</li>\n<li><code>Fast Setpoint</code>: Arbitriertes Solldrehmoment für den Stellpfad mit minimaler Reaktionszeitkonstante.</li>\n<li><code>PtTqWhl</code>: Vom Gesamtsystem am Rad bereitgestelltes Gesamtmoment (<em>Total wheel torque</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung erfolgt deterministisch im zyklischen Runnable-Kontext (periodische RTE-Events).</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1 (Führungsarbitrierung - Komfortebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Berechnung des vorläufigen Fahrer/VLC-Momentenwunsches:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Interm} = \\max(\\text{DrvReqTqWhlFast}, \\text{VlcTqWhlPtMin})$$</p>\n<p class=\"fig-p\">$$\\text{PtTqWhlReqDrvVlc} = \\min(\\text{Interm}, \\text{VlcTqWhlPtMax})$$</p>\n<ul class=\"fig-list\">\n<li>Evaluierung des Override-Flags:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{PtFlgDrvOvrdVlc} = (\\text{DrvReqTqWhlFast} \\equiv \\text{PtTqWhlReqDrvVlc})$$</p>\n<ol class=\"fig-list\">\n<li><strong>Koordinatentransformation (Clutch $\\to$ Wheel):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone Umrechnung der ESC-Kupplungsmomente in Radmomente über die aktuelle Gesamtübersetzung $i_{\\text{gear}} \\cdot i_{\\text{diff}}$:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{Whl}} = T_{\\text{Clu}} \\cdot i_{\\text{tot}} \\cdot \\eta_{\\text{driveline}}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2 (Sicherheitsarbitrierung - Chassisebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>MSR-Dominanz (<code>Max</code>-Glieder):</strong> Sowohl im Slow- als auch im Fast-Pfad wird das Vortriebsmoment nach unten durch das umgerechnete <code>EscTqCluPtMin</code> begrenzt, um Schlupf bei starkem Motorbremsmoment abzufangen:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{path, base}} = \\max(\\text{PtTqWhlReqDrvVlc}, \\text{EscTqCluPtMin\\_whl})$$</p>\n<ul class=\"fig-list\">\n<li><strong>ASR-Dominanz (<code>Min</code>-Glieder):</strong></li>\n<li><strong>Slow Path:</strong> Begrenzung auf <code>EscTqCluPtMaxSlow_whl</code> liefert <code>Slow setpoint</code>.</li>\n<li><strong>Fast Path:</strong> Begrenzung auf <code>EscTqCluPtMaxFast_whl</code> liefert <code>Fast Setpoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuatorische Distribution:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weitergabe an das nachgelagerte Motormanagement zur koordinierten Ansteuerung von Momentenstellgliedern unterschiedlicher Dynamik.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus (EXP):</strong> Das Dokument ist informativ/erläuternd (<em>Explanatory</em>). Die Struktur definiert empfohlene Application Interfaces (Port-Definitionen und Typisierung), schreibt jedoch nicht die interne Implementierungstopologie zwingend vor.</li>\n<li><strong>Inkonsistenz der Referenzebenen (Wheel vs. Clutch):</strong></li>\n<li>Eingangssignale mischen Radmomente (VLC, Fahrer) und Kupplungsmomente (ESC).</li>\n<li><em>Implementierungsfalle:</em> Die Blöcke <code>Conversion to wheel TQ</code> müssen bei Schaltvorgängen, Wandlerüberhöhung oder getrennter Kupplung hochdynamisch abgesichert werden. Bei offener Kupplung ($i_{\\text{tot}} \\to 0$ bzw. undefiniert) droht Division durch Null oder fehlerhafte Momentenskalierung.</li>\n<li><strong>Numerik des Komparators (<code>=</code>):</strong></li>\n<li>Der Komparator für <code>PtFlgDrvOvrdVlc</code> vergleicht Gleitkommagrößen (<code>float32</code> nach AUTOSAR-Standard). Ein direkter Identitätsvergleich (<code>==</code>) ist in Fixed-Point- oder Floating-Point-Arithmetik unzulässig; im Runnable muss ein Toleranzband ($|\\Delta T| \\le \\varepsilon$) mit Entprellung/Hysterese implementiert werden.</li>\n<li><strong>Echtzeit- und Task-Mapping:</strong></li>\n<li>Der <code>Fast Path</code> erfordert typischerweise ein Mapping in eine hochpriore, zyklische Task (z. B. $1\\,\\text{ms}$ bis $5\\,\\text{ms}$), um Stabilitätseingriffe des ESC verzögerungsarm abzubilden.</li>\n<li>Der <code>Slow Path</code> wird in der Regel in einer $10\\,\\text{ms}$- bis $20\\,\\text{ms}$-Task berechnet.</li>\n<li>Phasenverschiebungen und Totzeiten zwischen beiden Pfaden müssen im PTC über Momentenrampen und Vorsteuerfilter abgefangen werden, um Ruckeln und Triebstrangschwingungen zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-9465677856e8c6ae", "to": "FIG-1158af8e5d747ad7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildbeschnitt am oberen Rand: Die Portbezeichner am oberen Bildrand (<code>PtFlgDrvOvrdVlc</code> und <code>PtTqWhlReqDrvVlc</code>) wurden oben abgeschnitten, sodass nur noch die Erläuterungstexte <code>(=1 if both values are equal)</code> sowie <code>wheel torque by the driver or VLC</code> (teilweise abgeschnitten) sichtbar sind.</li>\n<li>Bildabmessungen: Reduzierung der Gesamthöhe von 570 px auf 500 px bei identischer Breite (854 px).</li>\n</ul>"}, {"from": "FIG-1158af8e5d747ad7", "to": "FIG-eeed95f6cec5f481", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eeed95f6cec5f481", "to": "FIG-43daa69d30a3d4b6", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-43daa69d30a3d4b6", "to": "FIG-eeed95f6cec5f481", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
